"""Automatic statement results, using the selected Soft Studio design system."""
CHECKUP_CSS = r'''
.topbar .studio-brand{min-width:0;flex:none}.topbar .friday-nav{flex:1;min-width:0}.topbar .friday-preference-actions{margin-left:auto;flex:none}.topbar .studio-account{margin-left:8px;flex:none}
.studio-welcome>p:not(.eyebrow):not(.studio-upload-note){max-width:55%;font-size:16px}.checkup-page>.screen-heading>p{display:none}.checkup-page>.screen-heading{margin-bottom:16px}.checkup-page>.screen-heading>h1{font-size:30px;margin:8px 0 14px}.checkup-finding{margin-top:10px;border:1px solid var(--line);border-radius:18px;background:var(--panel);overflow:hidden}.checkup-finding>summary{cursor:pointer;padding:18px;font-size:13px;font-weight:600;line-height:1.6;min-height:44px;box-sizing:border-box;list-style-position:inside}.checkup-finding[open]>summary{background:var(--studio-peach)}.checkup-finding>.checkup-card{margin:0;border:0;border-radius:0;background:var(--panel)}.checkup-finding>summary:focus-visible{outline:3px solid var(--blue);outline-offset:-4px}
.checkup{display:grid;gap:20px;min-width:0}.checkup-header{display:flex;align-items:center;justify-content:space-between;gap:14px}.checkup-header h2{font-size:29px;letter-spacing:-.04em;margin:0 0 7px}.checkup-header p,.checkup-quiet{font-size:12px;line-height:1.6;color:var(--muted);margin:0}.checkup-badge{display:inline-flex;align-items:center;gap:7px;padding:8px 12px;border-radius:20px;background:var(--studio-mint);font-size:11px;white-space:nowrap}
.checkup-kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.checkup-kpi{padding:18px;border-radius:20px;background:var(--studio-lilac);min-width:0}.checkup-kpi:nth-child(2){background:var(--studio-peach)}.checkup-kpi:nth-child(3){background:var(--studio-mint)}.checkup-kpi span{display:block;font-size:11px;margin-bottom:9px}.checkup-kpi strong{font-size:clamp(18px,2vw,26px);letter-spacing:-.04em;overflow-wrap:anywhere}
.checkup-tabs{display:flex;gap:6px;overflow:auto;scrollbar-width:thin;padding:4px;border:1px solid var(--line);border-radius:18px;background:var(--panel)}.checkup-tabs button{flex:1;min-height:44px;border:0;background:transparent;white-space:nowrap;font-size:12px;padding:9px 12px;box-shadow:none}.checkup-tabs button[aria-selected=true]{background:var(--studio-lilac);color:var(--blue)}
.checkup-panel{min-width:0}.checkup-panel h3{font-size:18px;letter-spacing:-.025em;margin:0 0 12px}.checkup-card{border:1px solid var(--line);border-radius:22px;padding:22px;background:var(--panel);min-width:0}.checkup-card p{font-size:13px;line-height:1.6;color:var(--muted);margin:8px 0}.checkup-card+.checkup-card{margin-top:12px}.checkup-card[data-tone=review]{background:var(--studio-peach)}.checkup-card[data-reviewed=true]{background:var(--panel2)}
.checkup-card-head{display:flex;justify-content:space-between;align-items:flex-start;gap:12px}.checkup-card-head h3{margin:0;font-size:17px}.checkup-card-head strong{font-size:18px;white-space:nowrap;letter-spacing:-.025em}.checkup-actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:15px}.checkup-actions button{min-height:44px;font-size:12px;padding:10px 13px}.checkup-actions .run{width:auto}.checkup-card small{font-size:11px;color:var(--muted)}
.checkup-viz-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.checkup-chart{height:240px;position:relative;min-width:0}.checkup-viz-grid .checkup-card{margin:0;padding:19px}.checkup-card details{margin-top:12px}.checkup-card summary,.checkup-proof summary{cursor:pointer;min-height:36px;line-height:1.5;font-size:12px;color:var(--blue)}.checkup-proof{font-size:12px;color:var(--muted);line-height:1.7}.checkup-proof ul{padding-left:20px}.checkup-evidence{max-height:310px;overflow:auto;margin-top:12px}.checkup-evidence table{width:100%;border-collapse:collapse;font-size:12px}.checkup-evidence th,.checkup-evidence td{padding:10px;text-align:left;border-bottom:1px solid var(--line);overflow-wrap:anywhere}.checkup-evidence td:nth-child(2){min-width:140px}.checkup-draft{width:100%;box-sizing:border-box;min-height:220px;resize:vertical;font-size:12px;line-height:1.7}.checkup-empty{border:1px dashed var(--line);border-radius:20px;padding:24px;background:var(--panel2)}.checkup-empty h3{margin-bottom:8px}.checkup-status{font-size:12px;line-height:1.7;color:var(--muted)}.checkup-mini{display:grid;gap:12px;margin-top:20px}.checkup-mini .checkup-header h2{font-size:24px}.checkup-mini .checkup-card{padding:18px}.checkup-mini .checkup-kpi{padding:14px}.checkup-mini .checkup-kpi strong{font-size:21px}.checkup-mini>button{justify-self:start}.checkup-search{display:block;width:100%;box-sizing:border-box;margin:12px 0}
@media(max-width:1200px){.topbar .shell{gap:16px}.topbar .studio-account-name{max-width:110px}.checkup-viz-grid{grid-template-columns:1fr}.checkup-chart{height:230px}.checkup-kpi{padding:14px}}
@media(max-width:950px){.topbar .friday-nav{flex:auto}.topbar .studio-account{margin-left:0}.checkup-viz-grid{grid-template-columns:1fr 1fr}}
@media(max-width:600px){.studio-welcome>p:not(.eyebrow):not(.studio-upload-note){max-width:100%}.checkup-header{align-items:flex-start}.checkup-header h2{font-size:25px}.checkup-badge{font-size:10px;padding:7px 9px}.checkup-kpis{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.checkup-kpi,.checkup-mini .checkup-kpi{padding:15px}.checkup-kpi:last-child{grid-column:1/-1;display:flex;align-items:center;justify-content:space-between;gap:10px}.checkup-kpi:last-child span{margin:0}.checkup-kpi strong,.checkup-mini .checkup-kpi strong{font-size:20px;white-space:nowrap;overflow:auto;max-width:100%}.checkup-viz-grid{grid-template-columns:1fr}.checkup-card{padding:18px}.checkup-card-head{display:block}.checkup-card-head strong{display:block;margin-top:10px}.checkup-tabs button{padding:8px 10px}.checkup-actions button{flex:1}.checkup-header p{max-width:210px}}
'''

CHECKUP_JS = r'''
    {
      let source=null,selectedTab='overview',selectedFinding=null,busy=false,epoch=0,preparedDraft=null;
      const mounts=new Map(),charts=new Map();
      views.dashboard.classList.add('checkup-page');views.dashboard.querySelector('h1').textContent='Your money, checked.';
      const money=scenarioMoney;
      const button=(label,action,cls='planner')=>{const b=element('button',label,cls);b.type='button';b.addEventListener('click',action);return b;};
      const current=data=>source&&data.revision===source.revision&&data.workspace_generation===source.workspace_generation;
      function ask(message){if(command.getAttribute('aria-busy')==='true'){toast('Friday is still replying.');return;}document.dispatchEvent(new CustomEvent('friday:share-statements-and-answer',{detail:{message}}));if(innerWidth<=950)show('coach');}
      function amountCard(label,value){const card=element('article',null,'checkup-kpi');card.append(element('span',label),element('strong',money(value)));return card;}
      function kpis(data){const s=data.summary,grid=element('div',null,'checkup-kpis');grid.append(amountCard('Identified income',s.totals.identified_income_minor),amountCard('Classified spending',s.totals.classified_spending_minor),amountCard('Recorded repayments',s.totals.loan_repayments_minor+s.totals.card_repayments_minor));return grid;}
      function clearCharts(target){(charts.get(target)||[]).forEach(c=>c.destroy());charts.set(target,[]);}
      function chart(target,parent,title,type,labels,values,colors){const card=element('section',null,'checkup-card');card.append(element('h3',title));const wrap=element('div',null,'checkup-chart'),canvas=element('canvas');canvas.setAttribute('role','img');canvas.setAttribute('aria-label',title+'. Exact values are available below.');wrap.append(canvas);card.append(wrap);parent.append(card);const detail=element('details');detail.append(element('summary','Exact figures'));const list=element('ul');labels.forEach((l,i)=>list.append(element('li',l+': '+money(values[i]))));detail.append(list);card.append(detail);queueMicrotask(()=>{if(!canvas.isConnected||!values.length||typeof Chart==='undefined'){wrap.hidden=true;detail.open=true;return;}const dark=document.documentElement.dataset.theme==='dark';const c=new Chart(canvas,{type,data:{labels,datasets:[{data:values,backgroundColor:colors,borderWidth:0,borderRadius:type==='bar'?8:undefined}]},options:{responsive:true,maintainAspectRatio:false,indexAxis:type==='bar'?'y':'x',animation:matchMedia('(prefers-reduced-motion:reduce)').matches||document.documentElement.dataset.motion==='off'?false:{duration:300},plugins:{legend:{display:type==='doughnut',position:'bottom',labels:{color:dark?'#eee9ff':'#30304c',boxWidth:9,font:{size:11}}},tooltip:{callbacks:{label:c=>c.label+': '+money(c.raw)}}},...(type==='bar'?{scales:{x:{ticks:{callback:v=>money(v),color:dark?'#d4cce3':'#656178'},grid:{color:dark?'#454052':'#eeeaf2'}},y:{ticks:{color:dark?'#eee9ff':'#30304c'},grid:{display:false}}}}:{cutout:'72%'})}});charts.get(target)?.push(c);});}
      function evidenceTable(rows){const wrap=element('div',null,'checkup-evidence'),table=element('table');const head=element('thead'),tr=element('tr');['Date','Statement entry','Amount','Source row'].forEach(label=>{const th=element('th',label);th.scope='col';tr.append(th);});head.append(tr);table.append(head);const body=element('tbody');rows.forEach(r=>{const row=element('tr');[r.date,r.description,money(r.debit_minor||r.credit_minor)+(r.debit_minor?' out':' in'),r.account_alias+' · row '+r.source_row].forEach(v=>row.append(element('td',v)));body.append(row);});table.append(body);wrap.append(table);return wrap;}
      function draftCard(parent,text){const section=element('section',null,'checkup-card');section.append(element('h3','Your enquiry is ready.'),element('p','Unsent. Review and redact before sending through your bank’s official channel.'));const label=element('label','Prepared enquiry'),field=element('textarea',text,'checkup-draft');field.readOnly=true;label.append(field);section.append(label);const download=button('Download enquiry',()=>{const blob=new Blob([text],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=element('a');a.href=url;a.download='friday-unsent-enquiry.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});section.append(download);parent.append(section);}
      function findingCard(f,data,expanded=false){const card=element('article',null,'checkup-card');card.dataset.tone='review';card.dataset.reviewed=String(f.reviewed);const head=element('div',null,'checkup-card-head');head.append(element('h3',f.title),element('strong',money(f.amount_minor)));card.append(head,element('small',f.reviewed?'Reviewed by you · not a legitimacy verdict':f.evidence_count+' source entries · review candidate'));if(expanded){card.append(element('p',f.detail),evidenceTable(f.evidence));const actions=element('div',null,'checkup-actions'),status=element('p','','checkup-status');status.setAttribute('role','status');
          const prepare=button('Prepare bank enquiry',async()=>{if(busy||!current(data))return;busy=true;prepare.disabled=true;mark.disabled=true;const sent=epoch;status.textContent='Assembling the dates, amounts and source rows…';try{const r=await jsonRequest('/api/friday/statements/findings/enquiry','POST',{finding_id:f.finding_id,expected_revision:data.revision,workspace_generation:data.workspace_generation});if(sent!==epoch||!current(data))return;if(r.sent!==false||r.source_revision!==data.revision||r.workspace_generation!==data.workspace_generation)throw new Error('Source changed');status.textContent='Prepared privately. Nothing was sent to a bank or Gemini.';draftBox.replaceChildren();draftCard(draftBox,r.draft);}catch{status.textContent='Enquiry was not confirmed. Reload My money before trying again.';}finally{busy=false;prepare.disabled=false;mark.disabled=false;}});
          const mark=button(f.reviewed?'Reopen finding':'Mark reviewed',async()=>{if(busy||!current(data))return;busy=true;mark.disabled=true;prepare.disabled=true;const sent=epoch;status.textContent='Saving your review status. Transactions stay unchanged.';try{const r=await jsonRequest('/api/friday/statements/findings/review','POST',{finding_id:f.finding_id,reviewed:!f.reviewed,expected_revision:data.revision,workspace_generation:data.workspace_generation});if(sent!==epoch)return;document.dispatchEvent(new CustomEvent('friday:statements-updated'));source=r;for(const [node,compact] of mounts)render(node,r,compact);toast(f.reviewed?'Finding reopened.':'Marked reviewed. No transaction changed.');}catch{status.textContent='Review status was not confirmed. Reload My money before trying again.';}finally{busy=false;mark.disabled=false;prepare.disabled=false;}});
          actions.append(prepare,mark);const draftBox=element('div');card.append(actions,status,draftBox);
        }else card.append(button('See what Friday found',()=>{selectedTab='findings';selectedFinding=f.finding_id;show('dashboard');refresh();}));return card;}
      function refresh(){if(source)for(const [node,compact] of mounts)render(node,source,compact);}
      function render(target,data,compact=false){if(source&&data.workspace_generation===source.workspace_generation&&data.revision<source.revision)return;mounts.set(target,compact);clearCharts(target);target.replaceChildren();if(data.checkup?.scope!=='AUTOMATIC_STATEMENT_CHECKUP'||data.checkup.money_moved!==false){target.append(element('p','Automatic checks are unavailable. Reload before relying on results.','statement-error'));return;}if(!current(data))epoch++;source=data;const s=data.summary,c=data.checkup,box=element('section',null,compact?'checkup checkup-mini':'checkup');box.setAttribute('aria-label','Friday statement checkup');target.append(box);if(!s.transaction_count){const empty=element('div',null,'checkup-empty');empty.append(element('h3','Less admin. A clearer money picture.'),element('p','Add a statement. I’ll check patterns and prepare the next step.'));box.append(empty);return;}
        const head=element('header',null,'checkup-header'),copy=element('div');if(compact)copy.append(element('h2','I’ve done the digging.'));copy.append(element('p',s.transaction_count+' transactions · '+s.period.start+' — '+s.period.end));head.append(copy,element('span',c.checks_completed.length+' checks completed','checkup-badge'));box.append(head,kpis(data));
        if(compact){const first=c.findings.find(f=>!f.reviewed);if(first)box.append(findingCard(first,data));else box.append(element('p','No open candidates from these checks. This is not proof every payment is legitimate.','checkup-quiet'));box.append(button('Open my money picture',()=>{selectedTab='overview';show('dashboard');},'run'));return;}
        const tabs=element('div',null,'checkup-tabs');tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Your money views');const panel=element('div',null,'checkup-panel');panel.id='friday-checkup-panel';panel.setAttribute('role','tabpanel');panel.tabIndex=0;
        [['overview','Overview'],['findings','Needs a look · '+c.open_count],['regular','Regular payments'],['transactions','Transactions']].forEach(([key,label])=>{const b=button(label,()=>{selectedTab=key;selectedFinding=null;render(target,data);},'');b.id='checkup-tab-'+key;b.setAttribute('role','tab');b.setAttribute('aria-selected',String(key===selectedTab));b.setAttribute('aria-controls',panel.id);b.tabIndex=key===selectedTab?0:-1;b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=['overview','findings','regular','transactions'];selectedTab=e.key==='Home'?keys[0]:e.key==='End'?keys[3]:keys[(keys.indexOf(key)+(e.key==='ArrowRight'?1:3))%4];render(target,data);$('checkup-tab-'+selectedTab).focus();});tabs.append(b);});panel.setAttribute('aria-labelledby','checkup-tab-'+selectedTab);box.append(tabs,panel);
        if(selectedTab==='overview'){
          const grid=element('div',null,'checkup-viz-grid');const colors=['#b7a0ed','#f2aa8c','#8fc9ad','#e8c46e','#85bad2','#d2a2c7','#adb3d9','#c3ce96','#d9b69c','#9cc6ca','#b2a9bd'];chart(target,grid,'Where it went','doughnut',s.categories.map(r=>r.category),s.categories.map(r=>r.amount_minor),colors);
          const change=c.spending_change;if(change){chart(target,grid,'What changed','bar',change.categories.slice(0,6).map(r=>r.category),change.categories.slice(0,6).map(r=>r.delta_minor),change.categories.slice(0,6).map(r=>r.delta_minor>0?'#e7a08d':'#84baa2'));grid.lastElementChild.append(element('p',change.previous_month+' → '+change.current_month+' · supplied spending, not necessarily full months.'));}else{const note=element('section',null,'checkup-card');note.append(element('h3','The bigger picture'),element('p',c.recurring.length+' regular payment pattern(s) found.'),element('p','Two consecutive supplied months unlock spending-change attribution.'));grid.append(note);}panel.append(grid);
          const actions=element('div',null,'checkup-actions');actions.append(button('Friday, summarise this · share totals',()=>ask('Summarise my automatic statement checkup. Show the highest priority finding and one useful next step.')));panel.append(actions);
        }else if(selectedTab==='findings'){
          panel.append(element('p','Worth reviewing, not confirmed fraud. Amounts are not added together as losses.','checkup-quiet'));const ordered=[...c.findings].sort((a,b)=>(a.finding_id===selectedFinding?-1:b.finding_id===selectedFinding?1:0));if(!ordered.length)panel.append(element('div','No candidates from the available checks. Missing evidence is not a safety certificate.','checkup-empty'));ordered.slice(0,40).forEach(f=>{const d=element('details',null,'checkup-finding');d.open=f.finding_id===selectedFinding;d.append(element('summary',f.title+' · '+money(f.amount_minor)+(f.reviewed?' · reviewed':'')),findingCard(f,data,true));panel.append(d);});if(ordered.length>40)panel.append(element('p','Showing the first 40 candidates. The full source rows remain in Transactions.','checkup-quiet'));
        }else if(selectedTab==='regular'){
          panel.append(element('p','Repeated monthly patterns, not confirmed subscriptions or future bills.','checkup-quiet'));if(!c.recurring.length)panel.append(element('div','No clear series yet. Matching descriptions in at least three consecutive months are needed.','checkup-empty'));c.recurring.forEach(r=>{const card=element('article',null,'checkup-card'),head=element('div',null,'checkup-card-head');head.append(element('h3',r.label),element('strong',money(r.latest_minor)));card.append(head,element('p',r.occurrences+' observed months · last '+r.last_date+' · '+r.account_alias));const detail=element('details');detail.append(element('summary','See source entries'),evidenceTable(r.evidence));card.append(detail);panel.append(card);});
        }else{
          const label=element('label','Find a transaction'),search=element('input',null,'checkup-search');search.type='search';search.placeholder='Search entries or accounts';label.append(search);panel.append(label);const rows=s.entries.map(r=>({...r})),table=evidenceTable(rows);const count=element('p',rows.length+' entries','checkup-status');count.setAttribute('role','status');search.addEventListener('input',()=>{let n=0;for(const tr of table.querySelectorAll('tbody tr')){tr.hidden=!tr.textContent.toLowerCase().includes(search.value.trim().toLowerCase());if(!tr.hidden)n++;}count.textContent=n+' matching entries';});panel.append(count,table);
        }
        if(selectedTab==='findings'&&preparedDraft&&preparedDraft.source_revision===data.revision&&preparedDraft.workspace_generation===data.workspace_generation)draftCard(panel,preparedDraft.draft);
        const proof=element('details',null,'checkup-proof');proof.append(element('summary',s.warnings.length?'Coverage & how Friday checked · '+s.warnings.length+' notes':'Coverage & how Friday checked'));const list=element('ul');[...s.warnings,...c.limits].forEach(t=>list.append(element('li',t)));proof.append(element('p',c.checks_completed.join(' · ')),list,element('p','Exact calculations and pattern rules run automatically on Friday’s server. Gemini explains shared derived totals only when you ask. No transaction descriptions are shared by the chat toggle.'));box.append(proof);
      }
      root.renderCheckup=render;
      const oldHome=root.renderStudioHome;root.renderStudioHome=function(target,data){oldHome(target,data);if(data.summary.transaction_count)render(target,data,true);};
      // A single optional, one-time conversation consent; never silently send CSV rows.
      const statementToggle=$('friday-chat-statements');const shareLabel=statementToggle?.closest('label')?.querySelector('span');if(shareLabel)shareLabel.textContent='Use my saved statement totals and derived checkup findings with Gemini · no transaction descriptions';
      const navSpending=document.querySelector('.friday-nav [data-screen-link=dashboard] span');if(navSpending)navSpending.textContent='My money';
      const advancedTools=element('button','Decision rehearsal');advancedTools.type='button';advancedTools.dataset.screenLink='rehearsal';moreItems.append(advancedTools);
      document.addEventListener('friday:portfolio-unavailable',()=>{source=null;epoch++;for(const [node] of mounts){clearCharts(node);node.replaceChildren(element('p','Statements are unavailable. Reload before using earlier results.','statement-error'));}});
      document.addEventListener('friday:cashflow-cleared',()=>{source=null;selectedFinding=null;preparedDraft=null;epoch++;for(const [node] of mounts){clearCharts(node);node.replaceChildren();}});
      document.addEventListener('friday:assistant-analysis',event=>{const v=event.detail.checkup_view;if(!v)return;if(!source||v.source_revision!==source.revision||v.workspace_generation!==source.workspace_generation){toast('Statements changed. Ask Friday again after reloading My money.');return;}selectedTab=({FINDINGS:'findings',REGULAR_PAYMENTS:'regular',SPENDING_CHANGE:'overview',PREPARE_ENQUIRY:'findings'})[v.action]||'overview';selectedFinding=v.finding_id;preparedDraft=v.draft?v:null;show('dashboard');refresh();});
      new MutationObserver(refresh).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme','data-motion']});
    }
'''
